css:
/* 圆角狂想：只动全局基元类（组件 scoped 样式带 data-v 哈希，皮肤选择器够不到） */
.lm-btn { border-radius: 999px; }
.lm-btn:hover { transform: translateY(-1px); }
.lm-btn:active { transform: scale(0.94); }
.lm-icon-btn:active { transform: scale(0.86) rotate(-8deg); }
.lm-glass { backdrop-filter: blur(36px) saturate(190%); -webkit-backdrop-filter: blur(36px) saturate(190%); }
